/**
 * Launch matrix: the command lines Cotal runs without a person typing them, generated by the code
 * that really writes them and run against the current binary.
 *
 * These callers outlive or bypass the public grammar: the manager and delivery daemon that `up`
 * starts, an owned manager unit `service install` writes, the delegated seat command an older
 * manager sends into a provider image, the bearer command a running seat execs, installed
 * completion stubs, the hand-wired completion line and the container commands in `deploy/`. Each
 * cell pins what the binary does with that line today, so a change to the command layer has to
 * keep it or change the cell on purpose. The bearer argv is written inline at its five call sites,
 * so its cell runs the flag set those sites write.
 *
 * A REAL broker, a REAL Manager started by `cotal up --detach`, and the real binary for every
 * cell. HOME, COTAL_HOME, XDG_CONFIG_HOME and the project root are sandboxed; `systemctl` is a stub
 * on PATH, so `service install` writes a real unit without touching the host's user manager. Needs
 * nats-server on PATH. Kills only the processes it starts.
 *
 * Run: pnpm smoke:launch-matrix:live
 */
import { spawn as spawnProc, spawnSync, type ChildProcess } from "node:child_process";
import { chmodSync, existsSync, mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { createConnection } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { SMOKE_BROKER_TOKEN, assertSmokeSandboxDown, createSuite, freePort, recordSmokeSandbox } from "@cotal-ai/smoke-kit";

const WT = join(import.meta.dirname, "..", "..");
const TSX = join(WT, "node_modules", ".bin", "tsx");
const BIN = join(WT, "bin", "cotal.ts");
const home = mkdtempSync(join(tmpdir(), "cotal-launch-matrix-home-"));
const root = mkdtempSync(join(tmpdir(), `${SMOKE_BROKER_TOKEN}launch-matrix-root-`));
const fgRoot = mkdtempSync(join(tmpdir(), `${SMOKE_BROKER_TOKEN}launch-matrix-fg-`));
const xdg = join(home, "xdg");
const stubBin = join(home, "stub-bin");
for (const dir of [join(root, ".cotal"), join(fgRoot, ".cotal"), xdg, stubBin]) mkdirSync(dir, { recursive: true });
const anchors = new Map([
  [root, recordSmokeSandbox({ root, cotalHome: join(home, ".cotal"), xdgConfigHome: xdg })],
  [fgRoot, recordSmokeSandbox({ root: fgRoot, cotalHome: join(home, ".cotal"), xdgConfigHome: xdg })],
]);
process.env.COTAL_HOME = join(home, ".cotal");
process.env.XDG_CONFIG_HOME = xdg;
const { delegatedSeatCommand, parseCommandArgs, registry, MANAGED_HANDOFF_FILE_ENV } = await import("@cotal-ai/core");
const { canonicalLocalProcessPath, readProcessRecord, DELIVERY_PIDFILE } = await import("@cotal-ai/workspace");
const { managerRecordState } = await import("../../implementations/cli/src/lib/manager-proc.js");
await import("@cotal-ai/cli");
await import("@cotal-ai/manager");
await import("@cotal-ai/delivery");

const SPACE = "launchmatrix";
const SERVER = `nats://127.0.0.1:${await freePort()}`;
const FG_SPACE = "launchmatrixfg";
const FG_PORT = await freePort();
const env: NodeJS.ProcessEnv = { ...process.env };
for (const key of Object.keys(env)) if (key.startsWith("COTAL_") || key === "INVOCATION_ID") delete env[key];
Object.assign(env, { HOME: home, COTAL_HOME: join(home, ".cotal"), XDG_CONFIG_HOME: xdg, COTAL_SKIP_CONNECTOR_SEED: "1", PATH: `${stubBin}:${process.env.PATH ?? ""}` });
const posixArgv = process.platform !== "win32";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const { check, finish } = createSuite();

function cotal(args: string[], opts: { cwd?: string; extraEnv?: NodeJS.ProcessEnv; timeout?: number } = {}) {
  const cwd = opts.cwd ?? root;
  const options = { cwd, env: { ...env, ...opts.extraEnv }, encoding: "utf8" as const, timeout: opts.timeout ?? 120_000 };
  assertSmokeSandboxDown(anchors.get(cwd), args, options);
  return spawnSync(TSX, [BIN, ...args], options);
}
const out = (r: ReturnType<typeof cotal>) => `${r.stdout ?? ""}${r.stderr ?? ""}`;
const portOpen = (port: number) => new Promise<boolean>((res) => {
  const s = createConnection({ host: "127.0.0.1", port }, () => { s.destroy(); res(true); });
  s.on("error", () => res(false));
  s.setTimeout(400, () => { s.destroy(); res(false); });
});
/** Whether a parsed argv resolves to a registered command without a usage error. */
function parses(argv: string[]): string | undefined {
  const cmd = registry.all<import("@cotal-ai/core").Command>("command").find((c) => c.name === argv[0]);
  if (!cmd) return `${argv[0]} is not a registered command`;
  try { parseCommandArgs(cmd, argv.slice(1)); return undefined; } catch (e) { return e instanceof Error ? e.message : String(e); }
}

const started: ChildProcess[] = [];
try {
  // ---- The manager and delivery daemon `up` starts -----------------------------------------------
  const up = cotal(["up", "--detach", "--space", SPACE, "--server", SERVER]);
  check("up --detach starts the authenticated stack", up.status === 0, out(up));
  if (posixArgv) {
    const manager = managerRecordState(undefined, undefined, SPACE, root).command ?? "";
    check("up starts the manager as `supervise --space <s> --server <url>`", manager.includes(` supervise --space ${SPACE} --server ${SERVER}`), manager);
    const delivery = readProcessRecord(canonicalLocalProcessPath(DELIVERY_PIDFILE, { root, space: SPACE }), () => true).command ?? "";
    check("up starts the delivery daemon as `deliver --space <s> --server <url>`", delivery.includes(` deliver --space ${SPACE} --server ${SERVER}`), delivery);
  } else console.log("  - skipped on win32: no process argv source for the started daemons");

  // ---- An owned manager unit, restarted on this binary ------------------------------------------
  if (process.platform === "linux") {
    writeFileSync(join(stubBin, "systemctl"), [
      "#!/bin/sh",
      `case "$*" in *show-environment*) echo "HOME=${home}"; echo "XDG_CONFIG_HOME=${xdg}";; *is-system-running*) echo running;; esac`,
      "exit 0", "",
    ].join("\n"));
    chmodSync(join(stubBin, "systemctl"), 0o755);
    // `service install` refuses beside a running manager, so the stack's own manager stops first and
    // the unit's command line is what brings one back.
    const down = cotal(["down", "manager"]);
    check("the stack's own manager stops before the unit is installed", down.status === 0, out(down));
    const install = cotal(["service", "install", "--mesh", SPACE], { timeout: 600_000 });
    check("service install writes an owned manager unit", install.status === 0, out(install));
    const unitDir = join(xdg, "systemd", "user");
    const unitName = spawnSync("sh", ["-c", `ls ${unitDir} | grep '^cotal-manager@.*\\.service$'`], { encoding: "utf8" }).stdout.trim();
    const unit = unitName ? readFileSync(join(unitDir, unitName), "utf8") : "";
    const execStart = /^ExecStart=(.*)$/m.exec(unit)?.[1] ?? "";
    const envFile = /^EnvironmentFile=(.*)$/m.exec(unit)?.[1] ?? "";
    const workDir = /^WorkingDirectory=(.*)$/m.exec(unit)?.[1] ?? "";
    check("the owned unit runs bare `supervise` in the mesh root with the mesh facts in its environment file",
      execStart.endsWith(" supervise") && existsSync(envFile) && workDir === root, { execStart, envFile, workDir });
    const unitEnv: NodeJS.ProcessEnv = {};
    for (const m of readFileSync(envFile, "utf8").matchAll(/^([A-Z_]+)="(.*)"$/gm)) unitEnv[m[1]!] = m[2]!.replace(/\\(["\\`$])/g, "$1");
    check("the unit environment names the space, server and a skipped lazy seed",
      unitEnv.COTAL_SPACE === SPACE && unitEnv.COTAL_SERVER === SERVER && unitEnv.COTAL_SKIP_CONNECTOR_SEED === "1", unitEnv);

    const [exe, ...unitArgs] = execStart.split(" ");
    const unitManager = spawnProc(exe!, unitArgs, { cwd: workDir, env: { PATH: env.PATH, ...unitEnv }, stdio: ["ignore", "pipe", "pipe"] });
    started.push(unitManager);
    let unitLog = "";
    unitManager.stdout?.on("data", (d) => { unitLog += d; });
    unitManager.stderr?.on("data", (d) => { unitLog += d; });
    let served = false;
    let lastPs = "";
    for (let i = 0; i < 30 && !served; i++) {
      const ps = cotal(["ps", "--space", SPACE], { timeout: 30_000 });
      served = ps.status === 0;
      lastPs = out(ps);
      if (!served) await sleep(1_000);
    }
    check("the unit's command line starts a manager that answers ps", served && unitManager.exitCode === null, { exit: unitManager.exitCode, lastPs: lastPs.slice(-600), unitLog: unitLog.slice(-1500) });
    unitManager.kill("SIGTERM");
  } else console.log(`  - skipped on ${process.platform}: the systemd unit arm`);

  // ---- The delegated seat command an older manager sends -----------------------------------------
  const persona = join(root, "delegated.md");
  writeFileSync(persona, "---\nname: delegated\n---\nA delegated seat.\n");
  const delegated = delegatedSeatCommand(
    { agent: "claude", persona: "", role: "worker", model: "m", launchOptions: { effort: "high" }, events: false },
    { space: SPACE, owner: "u_aaaaaaaaaaaaaaaaaaaaaa", actor: "delegated", lifecycleUid: "l".repeat(26) },
    { handoff: join(root, "handoff.json"), persona },
  );
  check("the delegated command parses under the current grammar", parses([...delegated.args]) === undefined, parses([...delegated.args]));
  const noHandoff = cotal([...delegated.args]);
  check("without its handoff file the delegated command refuses the expect flags",
    noHandoff.status === 1 && out(noHandoff).includes(`--expect-owner and --expect-lifecycle-uid apply only with ${MANAGED_HANDOFF_FILE_ENV}`), out(noHandoff));

  // ---- The bearer command a running seat execs -------------------------------------------------------
  const bearerDir = join(root, "bearer");
  mkdirSync(bearerDir, { recursive: true });
  const health = join(bearerDir, "health.json");
  const bearer = cotal(["agent-bearer", "--dir", bearerDir, "--space", SPACE, "--owner", "u_aaaaaaaaaaaaaaaaaaaaaa", "--actor", "seat",
    "--token-file", join(bearerDir, "missing.token"), "--health-file", health]);
  check("agent-bearer accepts the flag set its writers use and reaches the token read",
    bearer.status !== 0 && out(bearer).includes("can't read the actor token file"), out(bearer));
  check("agent-bearer records the failed attempt in the health file", existsSync(health) && readFileSync(health, "utf8").includes("failed"));

  // ---- Completion: installed stubs and the hand-wired line ------------------------------------------
  const install = cotal(["completion", "install", "bash"]);
  const stub = join(xdg, "cotal", "completion.bash");
  check("completion install writes a stub that calls `cotal __complete`",
    install.status === 0 && existsSync(stub) && readFileSync(stub, "utf8").includes("$(cotal __complete "), out(install));
  check("the rc file sources the stub", readFileSync(join(home, ".bashrc"), "utf8").includes(`source "${stub}"`));
  const completed = cotal(["__complete", "sp"]);
  check("__complete answers the stub's protocol", completed.status === 0 && /^spawn\t/m.test(completed.stdout), out(completed));
  const handWired = cotal(["completion", "bash"]);
  check("the hand-wired `completion bash` prints a script today", handWired.status === 0 && handWired.stdout.includes("__complete"), out(handWired));

  // ---- Container commands -------------------------------------------------------------------------
  const dockerCmd = JSON.parse(/^CMD (\[.*\])$/m.exec(readFileSync(join(WT, "deploy", "docker", "Dockerfile"), "utf8"))?.[1] ?? "[]") as string[];
  const composeCmds = [...readFileSync(join(WT, "deploy", "docker", "compose.yaml"), "utf8").matchAll(/^\s+command: (\[.*\])/gm)]
    .map((m) => JSON.parse(m[1]!) as string[]);
  check("deploy/ holds the Dockerfile CMD and both compose commands", dockerCmd.length > 0 && composeCmds.length === 2, { dockerCmd, composeCmds });
  for (const argv of [dockerCmd, ...composeCmds]) {
    // The entrypoint appends `--server "$COTAL_SERVERS"` to whatever command the container runs.
    const full = [...argv, "--server", "tls://broker.host:4222"];
    check(`container command \`${full.join(" ")}\` parses`, parses(full) === undefined, parses(full));
  }

  // ---- A foreground `up` in an operator unit ---------------------------------------------------------
  const fgServer = `nats://127.0.0.1:${FG_PORT}`;
  const fg = spawnProc(TSX, [BIN, "up", "--open", "--space", FG_SPACE, "--server", fgServer], { cwd: fgRoot, env, stdio: "ignore" });
  started.push(fg);
  let fgServing = false;
  for (let i = 0; i < 60 && !fgServing; i++) {
    fgServing = await portOpen(FG_PORT);
    if (!fgServing) await sleep(500);
  }
  await sleep(2_000);
  check("`up --space --server` without --detach serves and stays in the foreground", fgServing && fg.exitCode === null);
  fg.kill("SIGINT");
  const fgExit = await Promise.race([new Promise<number | null>((r) => fg.once("exit", (code) => r(code))), sleep(60_000).then(() => "timeout" as const)]);
  check("the foreground `up` exits on SIGINT", fgExit !== "timeout", fgExit);
} catch (e) {
  check(`suite ran without throwing: ${e instanceof Error ? e.message : String(e)}`, false, e instanceof Error ? e.stack : e);
} finally {
  for (const child of started) if (child.exitCode === null && child.signalCode === null) child.kill("SIGKILL");
  cotal(["down", "--space", SPACE]);
  cotal(["down", "--space", FG_SPACE], { cwd: fgRoot });
  finish();
  process.exit(process.exitCode ?? 0);
}
